steps.script:
for c in tree.root.get_children():
	if c is Window and c != tree.root and String(c.name) != "StratagemDialog":
		c.hide()
		c.queue_free()
return true

for c in tree.root.get_children():
	if c is Window and c != tree.root and String(c.name) != "BattleShockSequenceDialog":
		c.hide()
		c.queue_free()
return true

var cc = tree.current_scene.get_node_or_null("CommandController")
if cc == null:
	return "NO_CONTROLLER"
cc._refresh_ui()
return true
